args.sql:
SELECT COUNT(*) FROM accounts a
JOIN behavioral_scores bs ON a.acct_ref = bs.acct_beh
JOIN interaction_metrics im ON a.acct_ref = im.acct_dm;

SELECT COUNT(*) FROM account_clusters ac 
JOIN cluster_analysis ca ON ac.clu_ref = ca."CLSTR_PIN"
JOIN accounts a ON ac.acct_bridge = a.acct_ref;

SELECT COUNT(*) FROM account_clusters ac 
JOIN cluster_analysis ca ON ac.clu_ref = ca."CLSTR_PIN"
WHERE ac.acct_bridge IS NULL OR ca."CLSTR_PIN" IS NULL;

SELECT COUNT(DISTINCT ac.acct_bridge) FROM account_clusters ac 
JOIN cluster_analysis ca ON ac.clu_ref = ca."CLSTR_PIN"
WHERE NOT EXISTS (SELECT 1 FROM accounts a WHERE a.acct_ref = ac.acct_bridge);
